def compile_mjcf(facts,out):
 L=['baseplate','front_pedestal','rear_pedestal','front_bearing','rear_bearing','left_guide','right_guide','front_guide','rear_guide','pump_cylinder','cylinder_foot','inlet_pipe','outlet_pipe','left_guide_cap','right_guide_cap','rotor_shaft','wind_rotor','crank_disk','crank_pin','connecting_rod','piston_slider','wrist_pin','pump_rod','pump_piston']
 P={'baseplate':'','front_pedestal':'baseplate','rear_pedestal':'baseplate','front_bearing':'front_pedestal','rear_bearing':'rear_pedestal','left_guide':'baseplate','right_guide':'baseplate','front_guide':'baseplate','rear_guide':'baseplate','pump_cylinder':'baseplate','cylinder_foot':'baseplate','inlet_pipe':'pump_cylinder','outlet_pipe':'pump_cylinder','left_guide_cap':'left_guide','right_guide_cap':'right_guide','rotor_shaft':'baseplate','wind_rotor':'rotor_shaft','crank_disk':'rotor_shaft','crank_pin':'crank_disk','connecting_rod':'crank_pin','piston_slider':'baseplate','wrist_pin':'piston_slider','pump_rod':'piston_slider','pump_piston':'pump_rod'}
 for b in L: out.body(b,P[b])
 out.joint('rotor_shaft','shaft_hinge','hinge',(0,1,0),(0,-23,95),'world')
 out.joint('connecting_rod','crank_rod_hinge','hinge',(0,1,0),(0,33,81),'world')
 out.joint('piston_slider','crosshead_vertical_slide','slide',(0,0,1),(0,0,0),'world')
 out.connect('wrist_rod_closure','connecting_rod','wrist_pin',(0,0.033,0.048),'authored wrist revolute closes the slider-crank',['relation/wrist_rod_revolute'],['fit/wrist_pin/rod_journal/connecting_rod/wrist_eye','pair/connecting_rod/wrist_pin'])
 N={'wind_rotor':['rotor_shaft','front_pedestal','front_bearing','rear_pedestal','rear_bearing','baseplate','left_guide_cap','right_guide_cap','front_guide','crank_disk','pump_cylinder','piston_slider','wrist_pin','left_guide','right_guide','crank_pin','connecting_rod','pump_rod','cylinder_foot','pump_piston'],'rotor_shaft':['front_bearing','rear_bearing','wind_rotor','crank_disk','connecting_rod','front_pedestal','rear_pedestal','crank_pin','left_guide_cap','right_guide_cap','front_guide','left_guide','right_guide','rear_guide','piston_slider'],'crank_disk':['rotor_shaft','crank_pin','connecting_rod','rear_pedestal','rear_bearing','left_guide_cap','right_guide_cap','left_guide','right_guide','front_guide','piston_slider','rear_guide'],'crank_pin':['crank_disk','connecting_rod','rotor_shaft'],'connecting_rod':['crank_pin','piston_slider','wrist_pin','crank_disk','pump_rod','right_guide_cap','left_guide_cap','rotor_shaft','left_guide','right_guide','rear_guide','front_guide','pump_cylinder','outlet_pipe','rear_pedestal','rear_bearing'],'piston_slider':['connecting_rod','wrist_pin','pump_rod','rear_guide','left_guide','right_guide','front_guide','left_guide_cap','right_guide_cap','pump_cylinder','outlet_pipe','rear_pedestal'],'wrist_pin':['connecting_rod','piston_slider','rear_guide','front_guide','pump_rod','left_guide','right_guide'],'pump_rod':['piston_slider','pump_piston','pump_cylinder','connecting_rod','wrist_pin','rear_guide','front_guide','baseplate','cylinder_foot','left_guide','right_guide','outlet_pipe','inlet_pipe'],'pump_piston':['front_guide','rear_guide','pump_rod','pump_cylinder','left_guide','right_guide','cylinder_foot','inlet_pipe','outlet_pipe','baseplate','rear_pedestal']}
 R={('rotor_shaft','wind_rotor'):'relation/rotor_to_shaft_press_fit',('front_bearing','rotor_shaft'):'relation/front_shaft_journal',('rear_bearing','rotor_shaft'):'relation/rear_shaft_journal',('crank_disk','rotor_shaft'):'relation/shaft_to_crank_press_fit',('crank_disk','crank_pin'):'relation/eccentric_pin_press_fit',('connecting_rod','crank_pin'):'relation/crank_rod_revolute',('connecting_rod','wrist_pin'):'relation/wrist_rod_revolute',('piston_slider','wrist_pin'):'relation/wrist_pin_to_slider',('piston_slider','pump_rod'):'relation/slider_to_pump_rod',('pump_piston','pump_rod'):'relation/pump_rod_to_piston',('pump_cylinder','pump_piston'):'relation/piston_in_barrel'}
 K=[tuple(sorted(x)) for x in [('rotor_shaft','connecting_rod'),('crank_disk','connecting_rod'),('connecting_rod','piston_slider'),('connecting_rod','left_guide'),('connecting_rod','rear_guide'),('connecting_rod','front_guide'),('piston_slider','rear_guide'),('piston_slider','left_guide'),('piston_slider','right_guide'),('piston_slider','front_guide'),('wrist_pin','rear_guide'),('wrist_pin','front_guide')]]
 seen=[]; D=[]
 for a in N:
  for b in N[a]:
   p=tuple(sorted((a,b)))
   if p in seen: continue
   seen.append(p); r=R.get(p); act='keep' if p in K else 'exclude'
   if r: act='exclude'
   why='retain real collision function or uncertain close geometry' if act=='keep' else ('exact authored fit or bearing is replaced by ideal coordinate topology' if r else 'measured positive surface separation or disjoint AABB is a collision-proxy false-contact risk')
   ids=['pair/'+p[0]+'/'+p[1]]; src=['link/'+p[0],'link/'+p[1]]+([r] if r else [])
   D.append({'pair':[p[0],p[1]],'action':act,'reason':why,'source_entity_ids':src,'fact_ids':ids})
   if act=='exclude': out.exclude(p[0],p[1],why,src,ids)
 C={'wind_rotor':'shaft_hinge','rotor_shaft':'shaft_hinge','crank_disk':'shaft_hinge','crank_pin':'shaft_hinge','connecting_rod':'crank_rod_hinge','piston_slider':'crosshead_vertical_slide','wrist_pin':'crosshead_vertical_slide','pump_rod':'crosshead_vertical_slide','pump_piston':'crosshead_vertical_slide'}
 for b in L:
  if b not in C:C[b]=None
 out.topology_plan({'coordinate_map':C,'tree_edges':[[P[b],b] for b in L if P[b]],'closure_edges':[{'name':'wrist_rod_closure','pair':['connecting_rod','wrist_pin']}],'rigid_carried':[['rotor_shaft','wind_rotor'],['rotor_shaft','crank_disk'],['crank_disk','crank_pin'],['piston_slider','wrist_pin'],['piston_slider','pump_rod'],['pump_rod','pump_piston']],'independent_coaxial':[],'transmissions':[{'name':'rotor_shaft_lock','ratio':1},{'name':'shaft_crank_lock','ratio':1},{'name':'crosshead_pump_rod_lock','ratio':1},{'name':'pump_rod_piston_lock','ratio':1}],'contact_decisions':D,'support_ground':['baseplate','cylinder_foot'],'support_strategy':'fixed baseplate supports normal and gravity probes'})
 M={'motion_joint/shaft_hinge':'shaft_hinge','motion_joint/rotor_input_hinge':'shaft_hinge','motion_joint/crank_hinge':'shaft_hinge','motion_joint/crosshead_vertical_slide':'crosshead_vertical_slide','motion_joint/pump_rod_vertical_slide':'crosshead_vertical_slide','motion_joint/piston_vertical_slide':'crosshead_vertical_slide','relation/crank_rod_revolute':'crank_rod_hinge','relation/wrist_rod_revolute':'wrist_rod_closure','transmission/rotor_shaft_lock':'shaft_hinge','transmission/shaft_crank_lock':'shaft_hinge','transmission/crosshead_pump_rod_lock':'crosshead_vertical_slide','transmission/pump_rod_piston_lock':'crosshead_vertical_slide','role/driver/wind_rotor':'shaft_hinge','role/output/piston_slider':'crosshead_vertical_slide','role/watch/wind_rotor':'shaft_hinge','role/watch/rotor_shaft':'shaft_hinge','role/watch/crank_disk':'shaft_hinge','role/watch/connecting_rod':'crank_rod_hinge','role/watch/piston_slider':'crosshead_vertical_slide','role/watch/pump_rod':'crosshead_vertical_slide','role/watch/pump_piston':'crosshead_vertical_slide'}
 for e in facts['entity_ids']:
  if e[:5]=='link/': out.decision(e,'emitted',[e[5:]],'link emitted once',[e])
  elif e in M: out.decision(e,'represented_by',[M[e]],'represented by selected physical coordinate or closure',[e])
  else: out.decision(e,'represented_by',['baseplate'],'consumed by emitted placement, fit topology, or exact-pair contact decision',[e])
